} elseif ($worker === 'w1') {
    $hook = match ($state['mode']) { 'u1_unrelated_roots' => 'dzn_phase_2a2i_identity_root_locked', 'e_archive_initial', 'e_archive_replace' => 'dzn_phase_2a2j_teacher_archive_lock_held', default => 'dzn_phase_2a2j_assignment_locks_held' };
