function dzn_2a2j_race_close(int $id): void { global $wpdb; $p = $wpdb->prefix . 'dzn_'; $at = gmdate('Y-m-d H:i:s'); if ($wpdb->update($p . 'enrolments', array('lifecycle_state' => 'closed', 'applicable_slot' => null), array('id' => $id, 'lifecycle_state' => 'authorised', 'applicable_slot' => 1)) !== 1) throw new RuntimeException('Closure update failed'); if ($wpdb->insert($p . 'enrolment_lifecycle_events', array('uid' => \Delnavazan\Platform\Core\Support\Identifier::uid(), 'enrolment_id' => $id, 'event_sequence' => 2, 'from_state' => 'authorised', 'to_state' => 'closed', 'lineage_meaning' => null, 'reason_code' => 'synthetic_concurrency_closure', 'evidence_channel' => 'runtime_test', 'evidence_reference' => hash('sha256', 'closure:' . $id . ':' . wp_generate_uuid4()), 'occurred_at' => $at, 'recorded_at' => $at, 'recorded_by' => get_current_user_id(), 'created_at' => $at, 'created_by' => get_current_user_id())) !== 1) throw new RuntimeException('Closure evidence insert failed: ' . $wpdb->last_error); }
